187	    R._lastTimestamp = timestamp;
188	  }
189	  var rawDt = timestamp - R._lastTimestamp;
190	  R._lastTimestamp = timestamp;
191	  var dt = Math.min(rawDt, R.CONFIG.MAX_DT) / 1000; // ms → seconds
192	
193	  // --- update phase -----------------------------------------------------
194	  _callIfExists('updateInput');
195	
196	  R.updateStateMachine(dt);
197	
