     TRACK_CONTROL_POINTS, TRACK_SEGMENTS_PER_CP, TRACK_BASE_RADIUS,
     TRACK_RADIUS_VAR1/2/3, TRACK_RADIUS_JITTER, ROAD_WIDTH_MIN,
